import os, math
ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
src = os.path.join(ROOT, "SkyyCooking", "build_skyycooking_0.1.3.py")
dst = os.path.join(ROOT, "SkyyCooking", "build_skyycooking_0.1.4.py")
raw = open(src, encoding="utf8", newline="").read()
CR, LF = chr(13), chr(10)
NL = CR + LF if (CR + LF) in raw else LF
s = raw.replace(CR + LF, LF)


def rep(old, new):
    global s
    n = s.count(old)
    assert n == 1, "anchor count %d: %s" % (n, old[:120])
    s = s.replace(old, new, 1)


# the docstring tables are computed here from the same formulas the build uses (so a typo cannot slip in)
def _S(g): return (100 + 32 * g) / 100.0
def _D(g): return 2.0 ** (g / 5.0)
def _camp(g, f):
    if g <= 0 or f <= 0.0: return 0
    if f >= 1.0: return g
    t = 1.0 + f * (_S(g) - 1.0) + 1e-9
    return max([0] + [k for k in range(1, g + 1) if _S(k) <= t])
FACTOR_TABLE = ("     Grade     " + "".join("%6d" % g for g in range(1, 13)) + "\n"
                "     strength  " + "".join("%6.2f" % _S(g) for g in range(1, 13)) + "   S = 1 + 0.32 x Grade (0.1.3: = duration)\n"
                "     duration  " + "".join("%6.2f" % _D(g) for g in range(1, 13)) + "   D = 2^(Grade/5), unchanged\n")
CAMP_ROW = "  ".join("G%d->%d" % (g, _camp(g, 0.75)) for g in range(13))
assert [_camp(g, 0.75) for g in range(13)] == [0, 0, 1, 2, 3, 3, 4, 5, 6, 6, 7, 8, 9]

